const requiredFields = [
    'applicant_name', 'guardian_type', 'father_name',
    'india_village', 'india_po', 'india_ps',
    'india_district', 'india_pin', 'india_state',
    'bd_village', 'bd_po', 'bd_ps', 'bd_district',
    'entry_date', 'verification_date', 'advocate',
    'witness_name', 'witness_guardian_type', 'witness_father',
    'witness_age', 'witness_occupation',
    'witness_id_type', 'witness_id_number',
    'witness_village', 'witness_po', 'witness_ps',
    'witness_district', 'witness_pin', 'witness_state'
];

const body = items[0].json.body || {};
const missing = [];

for (const field of requiredFields) {
    if (!body[field] || String(body[field]).trim() === '') {
        missing.push(field);
    }
}

// Specific format validation
let formatError = null;
if (missing.length === 0) {
    if (!/^\d{6}$/.test(body.india_pin)) {
        formatError = 'Indian PIN code must be exactly 6 digits';
    }
    if (!/^\d{6}$/.test(body.witness_pin)) {
        formatError = 'Witness PIN code must be exactly 6 digits';
    }
    if (!/^\d{2}\/\d{2}\/\d{4}$/.test(body.entry_date)) {
        formatError = 'Entry date must be in DD/MM/YYYY format';
    } else {
        const [ed, em, ey] = body.entry_date.split('/').map(Number);
        const entryDate = new Date(ey, em - 1, ed);
        const cutoffDate = new Date(2014, 11, 31, 23, 59, 59);
        if (entryDate > cutoffDate || ey > 2014) {
            formatError = 'Under CAA 2019, Date of Entry must be on or before 31/12/2014';
        }
    }
    if (!/^\d{2}\/\d{2}\/\d{4}$/.test(body.verification_date)) {
        formatError = 'Verification date must be in DD/MM/YYYY format';
    }
    if (body.witness_id_type !== 'Aadhaar' && body.witness_id_type !== 'EPIC') {
        formatError = 'Witness ID type must be Aadhaar or EPIC';
    } else if (body.witness_id_type === 'Aadhaar' && !/^\d{12}$/.test(String(body.witness_id_number).replace(/\s/g, ''))) {
        formatError = 'Witness Aadhaar number must be exactly 12 digits';
    } else if (body.witness_id_type === 'EPIC' && !/^[A-Za-z0-9\/]{6,20}$/.test(String(body.witness_id_number).trim())) {
        formatError = 'Witness EPIC number must be 6-20 letters/digits';
    }
    if (!/^\d{1,3}$/.test(body.witness_age)) {
        formatError = 'Witness age must be a number';
    } else {
        const age = parseInt(body.witness_age, 10);
        if (age < 1 || age > 150) {
            formatError = 'Witness age must be between 1 and 150';
        }
    }
}

if (missing.length > 0) {
    return [{
        json: {
            isValid: false,
            error: `Missing required fields: ${missing.join(', ')}` 
        }
    }];
} else if (formatError) {
    return [{
        json: {
            isValid: false,
            error: formatError
        }
    }];
}

// Court Jurisdiction Header
const courtHeader = (body.custom_court && body.custom_court.trim()) 
    ? body.custom_court.trim() 
    : (body.court_header || 'Before the Notary Public at Barasat, North 24 Parganas');

// Normalize casing for legal formatting
const sanitizedData = {
    ...body,
    court_header: courtHeader,
    custom_court: courtHeader,
    applicant_name: body.applicant_name.toUpperCase().trim(),
    father_name: body.father_name.toUpperCase().trim(),
    india_village: body.india_village.toUpperCase().trim(),
    india_po: body.india_po.toUpperCase().trim(),
    india_ps: body.india_ps.toUpperCase().trim(),
    india_district: body.india_district.toUpperCase().trim(),
    bd_village: body.bd_village.toUpperCase().trim(),
    bd_po: body.bd_po.toUpperCase().trim(),
    bd_ps: body.bd_ps.toUpperCase().trim(),
    bd_district: body.bd_district.toUpperCase().trim(),
    witness_name: body.witness_name.toUpperCase().trim(),
    witness_father: body.witness_father.toUpperCase().trim(),
    witness_occupation: body.witness_occupation.toUpperCase().trim(),
    witness_id_number: body.witness_id_type === 'Aadhaar'
        ? String(body.witness_id_number).replace(/\D/g, '').replace(/(\d{4})(?=\d)/g, '$1 ')
        : String(body.witness_id_number).toUpperCase().trim(),
    witness_village: body.witness_village.toUpperCase().trim(),
    witness_po: body.witness_po.toUpperCase().trim(),
    witness_ps: body.witness_ps.toUpperCase().trim(),
    witness_district: body.witness_district.toUpperCase().trim()
};

return [{
    json: {
        isValid: true,
        data: sanitizedData
    }
}];
